do $$
declare
  n_records integer;
  n_links integer;
  n_minjun integer;
begin
  select count(*) into n_records from public.work_records
   where id::text >= '50000000-0000-4000-8000-000000000101' and id::text <= '50000000-0000-4000-8000-000000000133' and record_type = 'general' and status = 'sealed' and created_by = '1dfa3467-2cba-4e59-a834-6dabb7a77363';
  if n_records <> 33 then
    raise exception '시드 검증 실패: 새 관찰일지가 33건이어야 하는데 % 건이다', n_records;
  end if;

  select count(*) into n_links from public.work_record_students
   where work_record_id::text >= '50000000-0000-4000-8000-000000000101' and work_record_id::text <= '50000000-0000-4000-8000-000000000133';
  if n_links <> 72 then
    raise exception '시드 검증 실패: 학생 태그가 72건이어야 하는데 % 건이다', n_links;
  end if;

  select count(*) into n_minjun from public.work_record_students
   where work_record_id::text >= '50000000-0000-4000-8000-000000000101' and work_record_id::text <= '50000000-0000-4000-8000-000000000133' and enrollment_id = '40000000-0000-4000-8000-000000000001';
  if n_minjun <> 0 then
    raise exception '시드 검증 실패: 김민준은 태그하지 않아야 한다';
  end if;
end;
